<?php
require_once __DIR__.'/../../includes/layout.php'; require_login();
$month=(string)($_GET['month']??date('Y-m')); if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month) || (int)substr($month,0,4)<2000 || (int)substr($month,0,4)>2100) $month=date('Y-m');
$first=new DateTimeImmutable($month.'-01'); $days=(int)$first->format('t'); $offset=(int)$first->format('w');
$events=rows('SELECT * FROM events WHERE event_date>=? AND event_date<=? ORDER BY event_date,title',[$first->format('Y-m-d'),$first->format('Y-m-t')]);
$u=current_user();$schedule=[];
if($u['role']==='Teacher')$schedule=rows('SELECT sc.*,su.code FROM schedules sc JOIN subjects su ON su.id=sc.subject_id WHERE sc.teacher_id=? ORDER BY sc.day_of_week,sc.start_time',[teacher_id()]);
elseif(in_array($u['role'],['Student','Parent'],true))$schedule=rows('SELECT sc.*,su.code FROM schedules sc JOIN subjects su ON su.id=sc.subject_id WHERE sc.section_id IN(SELECT s.section_id FROM students s WHERE '.student_scope_sql().') ORDER BY sc.day_of_week,sc.start_time');
render_header('My school calendar'); ?>
<div class="page-title"><div><span class="eyebrow">CAMPUS LIFE</span><h1>Academic calendar</h1><p>Important dates and events maintained by your school.</p></div><?php if(in_array(current_user()['role'],['Admin','Super Admin'],true)): ?><a class="btn btn-primary" href="../admin/manage.php?entity=events">Manage events</a><?php endif; ?></div>
<div class="row g-4"><div class="col-lg-5"><section class="panel"><h2 class="panel-title"><a href="?month=<?= $first->modify('-1 month')->format('Y-m') ?>" aria-label="Previous month">←</a><?= e($first->format('F Y')) ?><a href="?month=<?= $first->modify('+1 month')->format('Y-m') ?>" aria-label="Next month">→</a></h2><div class="calendar-grid"><?php foreach(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as $day): ?><strong class="small text-muted"><?= $day ?></strong><?php endforeach; for($i=0;$i<$offset;$i++): ?><span></span><?php endfor; for($day=1;$day<=$days;$day++): $date=$month.'-'.str_pad((string)$day,2,'0',STR_PAD_LEFT); ?><span class="<?= $date===date('Y-m-d')?'today':'' ?>"><?= $day ?></span><?php endfor; ?></div></section></div><div class="col-lg-7"><section class="panel"><h2 class="panel-title">Events this month</h2><?php if(!$events): empty_state('No events scheduled','Events added by the administrator will appear here.'); endif; foreach($events as $event): ?><article class="activity-item"><span class="activity-icon"><i class="fa-regular fa-calendar"></i></span><div><strong><?= e($event['title']) ?></strong><p><?= e(date('F j, Y',strtotime($event['event_date']))) ?></p><p><?= e($event['description']) ?></p></div></article><?php endforeach; ?></section></div></div>
<div class="row g-4"><div class="col-lg-6"><section class="panel"><h2>My recurring classes</h2><?php if(!$schedule)empty_state('No classes assigned');foreach($schedule as $class): ?><article class="campus-event"><strong><?= e($class['code']) ?></strong><p><?= e($class['day_of_week'].' · '.$class['start_time'].'–'.$class['end_time'].' · '.$class['room']) ?></p></article><?php endforeach; ?></section></div><div class="col-lg-6"><section class="panel"><h2>Reserved visits & office availability</h2><p data-campus-feed-status role="status">Loading office calendar…</p><div data-campus-calendar></div></section></div></div>
<?php render_footer(); ?>
